<script lang="ts">import type { Resource } from '../../lib/api';export let accessMode:'direct'|'agent'='direct';export let endpoint='';export let accessKey='';export let secretKey='';export let sessionToken='';export let region='';export let secure=false;export let timeoutSeconds=10;export let mcpServerResourceId='';export let mcpServers:Resource[]=[];export let configurationAttempted=false;export let onConfigurationChange:()=>void=()=>{};</script>
{#if accessMode==='agent'}<label class:invalid={configurationAttempted&&!mcpServerResourceId}><span><i>*</i>关联 MCPServer</span><select bind:value={mcpServerResourceId} on:change={onConfigurationChange}><option value="">请选择活动的 MCPServer</option>{#each mcpServers as server}<option value={server.id}>{server.name}</option>{/each}</select></label><p class="docker-field-help">MinIO Agent 通过关联 MCPServer 提供统一只读工具。</p>{:else}<div class="docker-form-grid"><label class:invalid={configurationAttempted&&!endpoint.trim()}><span><i>*</i>Endpoint</span><input bind:value={endpoint} required on:input={onConfigurationChange} placeholder="例如 minio.example.com:9000" /></label><label><span>Access Key</span><input bind:value={accessKey} on:input={onConfigurationChange}/></label><label><span>Secret Key</span><input type="password" bind:value={secretKey} on:input={onConfigurationChange}/></label><label><span>Session Token</span><input type="password" bind:value={sessionToken} on:input={onConfigurationChange}/></label><label><span>Region</span><input bind:value={region} on:input={onConfigurationChange}/></label><label><span>超时时间（秒）</span><input type="number" min="1" max="300" bind:value={timeoutSeconds} on:input={onConfigurationChange}/></label><label><span>启用 HTTPS</span><input type="checkbox" bind:checked={secure} on:change={onConfigurationChange}/></label></div>{/if}
